-- Financeiro: ampliar apenas o módulo de planos; preservar as políticas existentes.
CREATE POLICY integracao_financeiro_operar ON public.planos_trabalho FOR ALL TO authenticated USING (EXISTS (SELECT 1 FROM public.profiles p WHERE p.id=(SELECT auth.uid()) AND p.ativo AND (lower(trim(p.tipo))='financeiro' OR lower(trim(coalesce(p.setor,'')))='financeiro'))) WITH CHECK (EXISTS (SELECT 1 FROM public.profiles p WHERE p.id=(SELECT auth.uid()) AND p.ativo AND (lower(trim(p.tipo))='financeiro' OR lower(trim(coalesce(p.setor,'')))='financeiro')));
